<?php
declare(strict_types=1);use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Branches\BranchContextService;use Vendi\Branches\BranchClock;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();if(($u['role']??'')!=='owner')throw new RuntimeException('Panel disponible para propietario.',403);$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);$ctx=new BranchContextService($db);$clock=new BranchClock($db);$wanted=$_GET['branch_id']??'all';$allowed=$ctx->available($u);$rows=[];$payments=[];$hours=array_fill(0,24,0.0);$peak=null;$total=0.0;$tickets=0;$cost=0.0;$products=[];$sellers=[];$alerts=[];$previousTotal=0.0;foreach($allowed as$b){if($wanted!=='all'&&(int)$wanted!==(int)$b['id'])continue;$bid=(int)$b['id'];$date=$clock->now((int)$u['business_id'],$bid)->format('Y-m-d');[$from,$to]=$clock->utcRangeForLocalDate((int)$u['business_id'],$bid,$date);$q=$db->prepare("SELECT COUNT(*) tickets,COALESCE(SUM(total),0) sales,COALESCE(SUM(cost_total),0) cost,COALESCE(AVG(total),0) avg_ticket,COALESCE(MAX(total),0) peak_sale FROM sales WHERE business_id=? AND branch_id=? AND status='completed' AND completed_at_utc>=? AND completed_at_utc<?");$q->execute([(int)$u['business_id'],$bid,$from,$to]);$x=$q->fetch();$rows[]=['id'=>$bid,'name'=>$b['name'],'timezone'=>$b['timezone'],'local_date'=>$date,'tickets'=>(int)$x['tickets'],'sales'=>(float)$x['sales'],'cost'=>(float)$x['cost'],'profit'=>(float)$x['sales']-(float)$x['cost'],'avg_ticket'=>(float)$x['avg_ticket']];$total+=(float)$x['sales'];$cost+=(float)$x['cost'];$tickets+=(int)$x['tickets'];
$prevDate=$clock->now((int)$u['business_id'],$bid)->modify('-1 day')->format('Y-m-d');[$pf,$pt]=$clock->utcRangeForLocalDate((int)$u['business_id'],$bid,$prevDate);$pq=$db->prepare("SELECT COALESCE(SUM(total),0) total FROM sales WHERE business_id=? AND branch_id=? AND status='completed' AND completed_at_utc>=? AND completed_at_utc<?");$pq->execute([(int)$u['business_id'],$bid,$pf,$pt]);$previousTotal+=(float)$pq->fetchColumn();
$tq=$db->prepare("SELECT sales_target FROM branch_daily_targets WHERE business_id=? AND branch_id=? AND target_date=? LIMIT 1");$tq->execute([(int)$u['business_id'],$bid,$date]);$target=(float)($tq->fetchColumn()?:0);$rows[array_key_last($rows)]['target']=$target;$rows[array_key_last($rows)]['target_pct']=$target>0?min(999,((float)$x['sales']/$target)*100):0;
$prod=$db->prepare("SELECT si.product_id,si.description,SUM(si.qty) qty,SUM(si.line_total) sales FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.business_id=? AND s.branch_id=? AND s.status='completed' AND s.completed_at_utc>=? AND s.completed_at_utc<? GROUP BY si.product_id,si.description");$prod->execute([(int)$u['business_id'],$bid,$from,$to]);foreach($prod->fetchAll()as$r){$key=(string)$r['product_id'];if(!isset($products[$key]))$products[$key]=['name'=>$r['description'],'qty'=>0.0,'sales'=>0.0];$products[$key]['qty']+=(float)$r['qty'];$products[$key]['sales']+=(float)$r['sales'];}
$sq=$db->prepare("SELECT u.id,u.name,COUNT(s.id) tickets,COALESCE(SUM(s.total),0) sales FROM sales s JOIN users u ON u.id=s.user_id WHERE s.business_id=? AND s.branch_id=? AND s.status='completed' AND s.completed_at_utc>=? AND s.completed_at_utc<? GROUP BY u.id,u.name");$sq->execute([(int)$u['business_id'],$bid,$from,$to]);foreach($sq->fetchAll()as$r){$key=(string)$r['id'];if(!isset($sellers[$key]))$sellers[$key]=['name'=>$r['name'],'tickets'=>0,'sales'=>0.0];$sellers[$key]['tickets']+=(int)$r['tickets'];$sellers[$key]['sales']+=(float)$r['sales'];}
$iq=$db->prepare("SELECT COUNT(*) FROM inventory WHERE business_id=? AND branch_id=? AND qty-reserved_qty<=min_qty");$iq->execute([(int)$u['business_id'],$bid]);$low=(int)$iq->fetchColumn();if($low>0)$alerts[]=['type'=>'inventory','level'=>$low>=10?'high':'medium','branch'=>$b['name'],'message'=>$low.' productos con inventario bajo'];if($target>0&&(float)$x['sales']<$target*.5&&((int)$clock->now((int)$u['business_id'],$bid)->format('H'))>=15)$alerts[]=['type'=>'target','level'=>'medium','branch'=>$b['name'],'message'=>'Venta por debajo del 50% de la meta diaria'];
$p=$db->prepare("SELECT COALESCE(pm.name,p.method,'Otro') method,COALESCE(SUM(p.amount-p.change_amount),0) total FROM payments p JOIN sales s ON s.id=p.sale_id LEFT JOIN payment_methods pm ON pm.id=p.payment_method_id WHERE s.business_id=? AND s.branch_id=? AND s.status='completed' AND s.completed_at_utc>=? AND s.completed_at_utc<? GROUP BY COALESCE(pm.name,p.method,'Otro')");$p->execute([(int)$u['business_id'],$bid,$from,$to]);foreach($p->fetchAll()as$r)$payments[$r['method']]=($payments[$r['method']]??0)+(float)$r['total'];
$h=$db->prepare("SELECT completed_at_utc,total FROM sales WHERE business_id=? AND branch_id=? AND status='completed' AND completed_at_utc>=? AND completed_at_utc<?");$h->execute([(int)$u['business_id'],$bid,$from,$to]);foreach($h->fetchAll()as$s){$local=$clock->displayUtc((int)$u['business_id'],$bid,$s['completed_at_utc']);$hour=(int)substr($local,11,2);$hours[$hour]+=(float)$s['total'];if(!$peak||(float)$s['total']>$peak['amount'])$peak=['amount'=>(float)$s['total'],'branch'=>$b['name'],'local_time'=>substr($local,11,5)];}}
usort($products,fn($a,$b)=>$b['sales']<=>$a['sales']);usort($sellers,fn($a,$b)=>$b['sales']<=>$a['sales']);$change=$previousTotal>0?(($total-$previousTotal)/$previousTotal)*100:null;echo json_encode(['ok'=>true,'generated_at'=>gmdate(DATE_ATOM),'branches'=>$allowed,'rows'=>$rows,'kpis'=>['sales'=>$total,'tickets'=>$tickets,'cost'=>$cost,'profit'=>$total-$cost,'avg_ticket'=>$tickets?$total/$tickets:0,'peak_sale'=>$peak,'previous_sales'=>$previousTotal,'change_vs_yesterday_pct'=>$change],'payments'=>array_map(fn($k,$v)=>['method'=>$k,'total'=>$v],array_keys($payments),array_values($payments)),'hourly'=>array_map(fn($h,$v)=>['hour'=>sprintf('%02d:00',$h),'sales'=>$v],array_keys($hours),array_values($hours)),'top_products'=>array_slice($products,0,8),'top_sellers'=>array_slice($sellers,0,8),'alerts'=>$alerts],JSON_UNESCAPED_UNICODE);}catch(Throwable$e){http_response_code(in_array((int)$e->getCode(),[401,403],true)?(int)$e->getCode():422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}